/** The string of a loc key (FText namespace and key), or undefined. */
export function findText(namespace: string, key: string): DemoString | undefined {
  const ns = Object.hasOwn(demoStrings, namespace) ? demoStrings[namespace] : undefined;
  return ns && Object.hasOwn(ns, key) ? ns[key] : undefined;
}

/** The string of a loc key in a language; throws when the key is unknown. */
export function text(namespace: string, key: string, lang: 'zh' | 'en' = 'zh'): string {
  const s = findText(namespace, key);
  if (!s) throw new Error(`unknown text ${namespace}/${key}`);
  return s[lang];
}
